('pdf2-q-003', 'imirongo', 'Umurongo uciyemo uduce umenyesha ahegereye umurongo ushobora kuzuzwa n''uturanga gukata tw''ibara ryera utwo turanga cyerekezo tumenyesha :', '', null, null, null, true, 162, false, 163),
('pdf2-q-004', 'imirongo', 'Ahantu ho kugendera mu muhanda herekanwa n''ibimenyetso bimurika ibinyabiziga ntibishobora kuhagenda :', '', null, null, null, true, 163, false, 164),
('pdf2-q-005', 'amategeko', 'Ibinyabiziga bikurikira bigomba gukorerwa isuzumwa buri mwaka:', '', null, null, null, true, 164, false, 165),
('pdf2-q-006', 'modoka', 'Ubugari bwa romoruki ikuruwe n''ikinyamitende itatu ntibugomba kurenza ibipimo bikurikira:', '', null, null, null, true, 165, false, 166),
('pdf2-q-007', 'modoka', 'Uburebure bw''ibinyabiziga bikurikira ntibugomba kurenga metero 11 :', '', null, null, null, true, 166, false, 167),
('pdf2-q-008', 'imyitwarire', 'Ikinyabiziga kibujijwe guhagarara akanya kanini aha hakurikira :', '', null, null, null, true, 167, false, 168),
('pdf2-q-009', 'imyitwarire', 'Kunyuranaho bikorerwa:', '', null, null, null, true, 168, false, 169),
('pdf2-q-010', 'modoka', 'Icyapa cyerekana umuvuduko ntarengwa ikinyabiziga kitagomba kurenza gishyirwa gusa ku binyabiziga bifite uburemere ntarengwa bukurikira:', '', null, null, null, true, 169, false, 170),
('pdf2-q-011', 'modoka', 'Ahatari mu nsisiro umuvuduko ntarengwa mu isaha wa velomoteri ni:', '', null, null, null, true, 170, false, 171),
('pdf2-q-012', 'umutekano', 'Umuyobozi ugenda mu muhanda igihe ubugari bwawo budatuma anyuranaho nta nkomyi ashobora kunyura mu kayira k''abanyamaguru ariko amaze kureba ibi bikurikira:', '', null, null, null, true, 171, false, 172),
('pdf2-q-013', 'amatara', 'Ku byerekeye kwerekana ibinyabiziga n''ukumurika kwabyo ndetse no kwerekana ihindura ry''ibyerekezo byabyo. Birabujijwe gukora andi matara cyangwa utugarurarumuri uretse ibitegetswe ariko ntibireba amatara akurikira:', '', null, null, null, true, 172, false, 173),
('pdf2-q-014', 'imyitwarire', 'Iyo nta mategeko awugabanya by''umwihariko umuvuduko ntarengwa w''amapikipiki mu isaha ni:', '', null, null, null, true, 173, false, 174),
('pdf2-q-015', 'modoka', 'Uburyo bukoreshwa kugirango ikinyabiziga kigende gahoro igihe feri idakora neza babwita:', '', null, null, null, true, 174, false, 175),
('pdf2-q-016', 'amategeko', 'Nibura ikinyabiziga gitegetswe kugira uduhanagurakirahure tungahe:', '', null, null, null, true, 175, false, 176),
('pdf2-q-017', 'amatara', 'Amatara maremare y''ikinyabiziga agomba kuzimwa mu bihe bikurikira:', '', null, null, null, true, 176, false, 177),
('pdf2-q-018', 'amatara', 'Ikinyabiziga ntigishobora kugira amatara arenga abiri y''ubwoko bumwe keretse kubyerekeye amatara akurikira:', '', null, null, null, true, 177, false, 178),
('pdf2-q-019', 'modoka', 'Ubugari bwa romoruki ikuruwe n''igare cyangwa velomoteri ntiburenza ibipimo bikurikira:', '', null, null, null, true, 178, false, 179),
('pdf2-q-020', 'amatara', 'Ibinyabiziga bikoreshwa nka tagisi, bitegerereza abantu mu nzira nyabagendwa, bishobora gushyirwaho itara ryerekana ko ikinyabiziga kitakodeshejwe. Iryo tara rishyirwaho ku buryo bukurikira:', '', null, null, null, true, 179, false, 180),
('pdf2-q-021', 'amatara', 'Za otobisi zagenewe gutwara abanyeshuri zishobora gushyirwaho amatara abiri asa n''icunga rihishije amyasa kugirango yerekane ko zihagaze no kwerekana ko bagomba kwitonda, ayo matara ashyirwaho ku buryo bukurikira :', '', null, null, null, true, 180, false, 181),
('pdf2-q-022', 'amatara', 'Itara ryo guhagarara ry''ibara ritukura rigomba kugaragara igihe ijuru rikeye nibura mu ntera ikurikira:', '', null, null, null, true, 181, false, 182),
('pdf2-q-023', 'modoka', 'Iyo umuvuduko w''ibinyabiziga bidapakiye ushobora kurenga km50 mu isaha ahategamye, bigomba kuba bifite ibikoresho by''ihoni byumvikanira mu ntera:', '', null, null, null, true, 182, false, 183),
('pdf2-q-024', 'modoka', 'Birabujijwe kugenza ibinyabiziga bigendeshwa na moteri naza romoruki zikururwa nabyo, iyo ibiziga byambaye inziga zidahagwa cyangwa inziga zikururuka zifite umubyimba uri hasi ya cm 4. Ariko ibyo ntibikurikizwa kubinyabiziga bikurikira:', '', null, null, null, true, 183, false, 184),
('pdf2-q-025', 'modoka', 'Igice cy''inzira nyabagendwa kigarukira ku mirongo ibiri yera icagaguye ibangikanye kandi gifite ubugari budahagije kugira ngo imodoka zitambuke neza, kiba ari:', '', null, null, null, true, 184, false, 185),
('pdf2-q-026', 'modoka', 'Ubugari bwa romoruki ntiburenza ubugari bw''ikinyabiziga kiyikurura iyo ikuruwe n''ibinyabiziga bikurikira:', '', null, null, null, true, 185, false, 186),
('pdf2-q-027', 'umutekano', 'Iyo hatarimo indi myanya birabujijwe gutwara ku ntebe y''imbere y''imodoka abana badafite imyaka:', '', null, null, null, true, 186, false, 187),
('pdf2-q-028', 'amategeko', 'Icyapa kivuga gutambuka mbere y''ibinyabiziga biturutse imbere gifite amabara akurikira:', '', null, null, null, true, 187, false, 188),
('pdf2-q-029', 'amategeko', 'Ni ryari itegeko rigenga gutambuka mbere kw''iburyo rikurikizwa mu masangano:', '', null, null, null, true, 188, false, 189),
('pdf2-q-030', 'amategeko', 'Ibimenyetso bimurika byerekana uburyo bwo kugendera mu muhanda kw''ibinyabiziga bishyirwa iburyo bw''umuhanda. Ariko bishobora no gushyirwa ibumoso cyangwa hejuru y''umuhanda:', '', null, null, null, true, 189, false, 190),
('pdf2-q-031', 'amatara', 'Iyo itara ry''umuhondo rimyatsa rikoreshejwe mu masangano y''amayira ahwanyije agaciro rishyirwa ahagana he:', '', null, null, null, true, 190, false, 191),
('pdf2-q-032', 'amategeko', 'Inkombe z''inzira nyabagendwa cyangwa z''umuhanda zishobora kugaragazwa n''ibikoresho ngarurarumuri. Ibyo bikoresho bigomba gushyirwaho ku buryo abagenzi babibona :', '', null, null, null, true, 191, false, 192),
('pdf2-q-033', 'amategeko', 'Ibinyabiziga bikurikira bigomba gukorerwa isuzumwa rimwe mu mezi 6:', '', null, null, null, true, 192, false, 193),
('pdf2-q-035', 'amategeko', 'Ku mihanda ibyapa bikurikira bigomba kugaragazwa ku buryo bumwe:', '', null, null, null, true, 193, false, 194),
('pdf2-q-036', 'modoka', 'Ni iyihe feri ituma imodoka igenda buhoro kandi igahagarara ku buryo bwizewe bubangutse kandi nyabwo, uko imodoka yaba yikoreye kose yaba igeze ahacuramye cyangwa ahaterera:', '', null, null, null, true, 194, false, 195),
('pdf2-q-038', 'modoka', 'Uretse mu mujyi, ku yindi mihanda yajyenwe na minisitiri ushinzwe gutwara abantu n''ibintu, uburemere ntarengwa ku binyabiziga bifite imitambiko itatu cyangwa irenga hatarimo makuzungu ni :', '', null, null, null, true, 195, false, 196),
('pdf2-q-039', 'modoka', 'Ubugari bw''imizigo yikorewe n''ibinyamitende itatu n''ubwiyikorewe n''ibinyamitende 4 bifite cyangwa bidafite moteri kimwe n''ubw''iyikorewe na romuruki zikuruwe n''ibyo binyabiziga ntibushobora kurenga ibipimo bikurikira:', '', null, null, null, true, 196, false, 197),
('pdf2-q-040', 'umutekano', 'Kunyura ku binyabiziga bindi, uretse icy''ibiziga bibiri, bibujijwe aha hakurikira:', '', null, null, null, true, 197, false, 198),
('pdf2-q-041', 'imyitwarire', 'Iyo nta mategeko awugabanya by''umwihariko, umuvuduko ntarengwa ku modoka zitwara abagenzi mu buryo bwa rusange ni:', '', null, null, null, true, 198, false, 199),
('pdf2-q-042', 'modoka', 'Iyo nta mategeko awugabanya by''umwihariko, umuvuduko ntarengwa ku modoka zikoreshwa nk''amavatiri y''ifasi cyangwa amatagisi zifite uburemere bwemewe butarenga kilogarama 3500 ni:', '', null, null, null, true, 199, false, 200),
('pdf2-q-045', 'umutekano', 'Utuyira turi ku mpande z''umuhanda n'' inkengero zigiye hejuru biharirwa abanyamaguru mu bihe bikurikira:', '', null, null, null, true, 200, false, 201),
('pdf2-q-047', 'modoka', 'Uburemere ntarengwa bwemewe ntibushobora kurenga ½ cy''uburemere bw''ikinyabiziga gikurura nubw''umuyobozi kuri romoruki zikurikira :', '', null, null, null, true, 201, false, 202),
('pdf2-q-048', 'amatara', 'Ibinyabiziga bifite ubugari bufite ibipimo bikurikira bigomba kugira amatara ndangaburumbarare :', '', null, null, null, true, 202, false, 203),
('pdf2-q-049', 'amatara', 'Nta tara na rimwe cyangwa akagarurarumuri bishobora kuba bifunze ku buryo igice cyabyo cyo hasi cyane kimurika kitaba kiri hasi y''ibipimo bikurikira kuva ku butaka igihe ikinyabiziga kidapakiye :', '', null, null, null, true, 203, false, 204),
('pdf2-q-050', 'imirongo', 'Iyo ikinyabiziga gifite amatara abiri cyangwa menshi y''ubwoko bumwe ayo matara agomba kugira ibara rimwe n''ingufu zingana kandi akagomba gushyirwaho ku buryo buteganye uhereye ku murongo ugabanya ikinyabizigamo kabiri mu burebure bwacyo. Ariko ibi ntibikurikizwa ku matara akurikira:', '', null, null, null, true, 204, false, 205),
('pdf2-q-051', 'amatara', 'Ahari hejuru cyane y''ubuso bumurika h''amatara ndangambere na ndanganyuma ntihashobora kuba aharenze ibipimo bikurikira hejuru y''ubutaka iyo ikinyabiziga kidapakiye:', '', null, null, null, true, 205, false, 206),
('pdf2-q-052', 'modoka', 'Ni ryari ikinyabiziga gishobora kugenda mu muhanda moteri itaka cyangwa vitesi idakora:', '', null, null, null, true, 206, false, 207),
('pdf2-q-053', 'imirongo', 'Umurongo mugari wera udacagaguye ushobora gucibwa ku muhanda kugirango ugaragaze ibi bikurikira:', '', null, null, null, true, 207, false, 208),
('pdf2-q-055', 'imyitwarire', 'Ibinyabiziga bikurikira bigomba kugira icyerekana umuvuduko kiri aho umuyobozi areba neza kandi kigahora kitabwaho kugirango kigume gukora neza:', '', null, null, null, true, 208, false, 209),
('pdf2-q-056', 'modoka', 'Ubugari bw''imizigo yikorewe n''ipikipiki idafite akanyabiziga ko kuruhande kimwe n''ubwa romoruki ikuruwe na bene icyo kinyabiziga ntibushobora kurenza ibipimo bikurikira:', '', null, null, null, true, 209, false, 210),
('pdf2-q-057', 'amatara', 'Ibinyabiziga bikurikira bigomba kugira itara ry''ubururu rimyatsa riboneka mu mpande zose:', '', null, null, null, true, 210, false, 211),
('pdf2-q-058', 'amatara', 'Ibinyabiziga bihinga n''ibindi bikoresho byihariye bikoreshwa n''ibigo bipatana imirimo, iyo bigenda mu nzira nyabagendwa igihe cya nijoro cyangwa bitewe n''uko ibihe bimeze bitagishoboka kubona neza muri m 200 bishobora kugaragazwa inyuma n''amatara 2 atukura, bipfa kuba bitarenza ibipimo bikurikira:', '', null, null, null, true, 211, false, 212),
('pdf2-q-059', 'amatara', 'Iyo romoruki iziritse ku kinyamitende, velomoteri n''amapikipiki bidafite akanyabiziga ko kuruhande uretse ikinyamitende na velomoteri bidafite umuyobozi, iyo uburumbarare bwayo cyangwa bw''ibyo yikoreye bituma itara ry''ikinyabiziga gikurura ritagaragara igihe bitagishoboka kubona neza muri m 200 bigomba kugaragazwa ku buryo bukurikira:', '', null, null, null, true, 212, false, 213),
('pdf2-q-060', 'amategeko', 'Ku kinyabiziga cyangwa ibinyabiziga bikururana igice kirenga ku biziga ntikigomba kurenga ibipimo bikurikira:', '', null, null, null, true, 213, false, 214),
('pdf2-q-061', 'amatara', 'Iyo amatara y''ikinyabiziga agomba gucanwa kandi igihe imizigo isumba impera y''ikinyabiziga ho metero irenga igice gihera cy''imizigo kigaragazwa ku buryo bukurikira:', '', null, null, null, true, 214, false, 215),
('pdf2-q-062', 'modoka', 'Iyo imizigo igizwe n''ibinyampeke, ikawa, ipamba idatonoye, ibishara, ibyatsi, ibishami cyangwa ubwatsi bw''amatungo bidahambiriye uretse amapaki afunze, ubugari bwayo bushobora kugera ku bipimo bikurikira:', '', null, null, null, true, 215, false, 216),
('pdf2-q-063', 'modoka', 'Uretse mu mijyi kuyindi mihanda yagenywe na minisiteri ushinzwe gutwara ibintu n''abantu, uburemere ntarengwa bwemewe ku binyabiziga bifatanye bifite imitambiko itatu ni:', '', null, null, null, true, 216, false, 217),
('pdf2-q-064', 'amatara', 'Buri modoka cyangwa buri romoruki ikuruwe n''iyo modoka bishobora kugira itara rituma umuyobozi yerekana ko yabonye ikimenyetso cy''uwitegura kumunyuraho. Iryo tara rifite amabara akurikira:', '', null, null, null, true, 217, false, 218),
('pdf2-q-065', 'modoka', 'Ikinyabiziga cyangwa ibinyabiziga bikururana bifite imitambiko ibiri ikurikiranye mu bugari bwayo ni ukuvuga imitambiko yihindukiza kucyo ifungiyeho, uburebure bwabyo ntibugomba kurenza ibipimo bikurikira:', '', null, null, null, true, 218, false, 219),
('pdf2-q-066', 'modoka', 'Bumwe muri ubu bwoko bwa feri ituma imodoka iguma aho iri uko yaba yikoreye kose ku muzamuko cyangwa ku gacuri bya 16%, imyanya ya feri igomba gufata igakomeza kwegera kuburyo bw''ibyuma niyo umuyobozi yaba atarimo:', '', null, null, null, true, 219, false, 220),
('pdf2-q-067', 'amatara', 'Utugarurarumuri turi mu mbavu z''ikinyabiziga tugomba kugira ibara rikurikira:', '', null, null, null, true, 220, false, 221),
('pdf2-q-068', 'amatara', 'Romoruki zifite ubugari ntarengwa bwa cm 80 zishobora gushyirwaho akagarurarumuri kamwe gusa iyo zikuruwe n''ibinyabiziga bikurikira:', '', null, null, null, true, 221, false, 222),
('pdf2-q-069', 'amatara', 'Amatara maremare y''ibara ryera cyangwa ry''umuhondo agomba, nijoro igihe ijuru rikeye, kumurika mu muhanda mu ntera ya m 100 nibura imbere y''ikinyabiziga, ariko ku binyabiziga bifite moteri itarengeje za sentimetero kibe 125 iyo ntera igira ibipimo bikurikira:', '', null, null, null, true, 222, false, 223),
('pdf2-q-070', 'umutekano', 'Iyo banyuze iruhande rw''inkomyi abanyamaguru bagomba gukikira banyuze mu muhanda, abayobozi bagomba gusiga umwanya ufite ubugari bwa m 1 nibura hagati yabo nayo. Iyo ibyo bidashobora kubahirizwa kandi umunyamaguru akaba anyura hafi yiyo nkomyi, umuyobozi agomba kuyikikira afite umuvuduko utarengeje ibipimo bikurikira:', '', null, null, null, true, 223, false, 224),
('pdf2-q-071', 'imyitwarire', 'Guhagarara akanya gato no guhagarara akanya kanini bibujijwe cyane cyane aha hakurikira:', '', null, null, null, true, 224, false, 225),
('pdf2-q-072', 'amatara', 'Amatara ndangambere n''aya ndanganyuma y''imodoka zitarengeje m 6 z''uburebure na m 2 z''ubugari habariwemo imitwaro kdi nta kinyabiziga kindi kiziritseho ashobora gusimburwa n''amatara akurikira, iyo ibyo binyabiziga bihagaze umwanya muto cyangwa munini mu nsisiro bibangikanye ku ruhande rw''umuhanda:', '', null, null, null, true, 225, false, 226),
('pdf2-q-073', 'imirongo', 'Iyo kuva bwije kugeza bukeye cyangwa bitewe nuko ibihe bimeze nk''igihe cy''igihu cyangwa cy''imvura bitagishoboka kubona neza muri m 200, imirongo y''ingabo z''igihugu zigendera kuri gahunda n''utundi dutsiko twose tw''abanyamaguru nk''imperekerane cyangwa udutsiko tw''abanyeshuri bari ku murongo bayobowe na mwarimu, iyo bagenda mu muhanda ku isonga hakaba hari abantu barenze umwe, bagaragzwa ku buryo bukurikira:', '', null, null, null, true, 226, false, 227),
('pdf2-q-074', 'modoka', 'Imizigo yikorewe n''amagare, velomoteri, amapikipiki, ibinyamitende by''ibiziga bitatu nibyo ibiziga bine bifite cyangwa bidafite moteri inyuma ntishobora kurenza ibipimo bikurikira:', '', null, null, null, true, 227, false, 228),
('pdf2-q-075', 'amatara', 'Itara ndanganyuma rigomba gushyirwa aha hakurikira:', '', null, null, null, true, 228, false, 229),
('pdf2-q-076', 'amatara', 'Nta tara na rimwe cyangwa utugarurarumuri bishobora kuba bifunze kuburyo igice cyabyo cyo hasi cyane kimurika kitaba kiri hasi ya cm 40 kuva ku butaka igihe ikinyabiziga kidapakiye ariko ibyo ntibikurikizwa ku matara akurikira:', '', null, null, null, true, 229, false, 230),
('pdf2-q-077', 'amatara', 'Iyo tumuritswe n''amatara y''urugendo y''i kinyabiziga utugarurarumuri tugomba n''ijoro, igihe ijuru rikeye kubonwa n''umuyobozi w''ikinyabiziga kiri mu ntera ikurikira:', '', null, null, null, true, 230, false, 231),
('pdf2-q-078', 'modoka', 'Ibinyabiziga bigendeshwa na moteri, hatarimo velomoteri n''ibinyabiziga bidapakiye umuvuduko wabyo udashobora kurenga km 50 mu isaha ahateganye bigomba kuba bifite ibikoresho by''ihoni byumvikanira mu ntera ikurikira:', '', null, null, null, true, 231, false, 232),
('pdf2-q-079', 'amategeko', 'Ahatari mu nsisiro ibyapa biburira n''ibyapa byo gutambuka mbere bigomba gushyirwa mu ntera ikurikira y''ahantu habyerekana:', '', null, null, null, true, 232, false, 233),
('pdf2-q-080', 'amategeko', 'Inkombe z''inzira nyabagendwa cyangwa z''umuhanda zishobora kugaragazwa n''ibikoresho ngarurarumuri. Ibyo bikoresho bigomba gushyirwaho ku buryo abagenzi babibona ku buryo bukurikira:', '', null, null, null, true, 233, false, 234),
('pdf2-q-081', 'umutekano', 'Ahatari mu nsisiro, umuyobozi wese ugenza ikinyabiziga kimwe cyangwa ibinyabiziga bikomatanye bifite uburemere ntarengwa bwemewe burenga ibiro 3500 cyangwa bifite uburebure bwite burenga metero 10 agomba, keretse iyo anyuze cyangwa agiye kunyura ku bindi binyabiziga, gusiga hagati y''ikinyabiziga cye n''iki muri imbere umwanya uhagije kugirango ibinyabiziga bimuhiseho bishobore kuhigobeka bidateje impanuka igihe bibaye ngombwa ariko ibyo ntibikurikizwa mu bihe bikurikira:', '', null, null, null, true, 234, false, 235),
('pdf2-q-082', 'modoka', 'Ibiziga by''ibinyabiziga bigendeshwa na moteri n''ibya velomoteri kimwe n''ibya romoruki zabyo bigomba kuba byambaye inziga zihagwa zifite amano n''ubujyakuzimu butari munsi ya milimetero imwe ku migongo yabyo yose nubudodo bwabyo ntibugire ahantu na hamwe bugaragara kandi ntibugire aho byacitse bikomeye mu mpande zabyo ariko ibyo ntibikurikizwa ku binyabiziga bikurikira:', '', null, null, null, true, 235, false, 236),
('pdf2-q-083', 'amatara', 'Amatara ndangacyerekezo agomba kuba agizwe n''ibintu bifashe ku rumuri rumyasa, biringaniye ku buryo bigira umubare utari igiharwe ku mpande z''imbere n''inyuma z''ikinyabiziga ayo matara aba afite amabara akurikira:', '', null, null, null, true, 236, false, 237),
('pdf2-q-084', 'modoka', 'Amahoni y''ibinyabiziga bigendeshwa na moteri agomba kohereza ijwi ry''injyana imwe rikomeza kandi ridacengera amatwi ariko ibinyabiziga bikurikira bishobora kugira ihoni ridasanzwe ridahuye n''ibivuzwe haruguru:', '', null, null, null, true, 237, false, 238),
('pdf2-q-085', 'amategeko', 'Icyapa kibuza kunyura kubindi binyabiziga byose uretse ibinyamitende ibiri n''amapikipiki adafite akanyabiziga ku ruhande gifite ibimenyetso by''amabara akurikira:', '', null, null, null, true, 238, false, 239),
('pdf2-q-086', 'amategeko', 'Icyapa kivuga ko hatanyurwa mu byerekezo byombi kirangwa n''ubuso bw''ibara rikurikira:', '', null, null, null, true, 239, false, 240),
('pdf2-q-087', 'modoka', 'Ibinyabiziga bikurikira bigomba kugira ibikoresho by''ihoni byumvikanira mu ntera ya m 20:', '', null, null, null, true, 240, false, 241),
('pdf2-q-088', 'imirongo', 'Imirongo y''ingabo z''igihugu zigendera kuri gahunda n''utundi dutsiko twose tw''abanyamaguru nk''imperekerane cyangwa udutsiko tw''abanyeshuri iyo bitagishoboka kubona neza muri m200, bagaragazwa ni itara ryera imbere naho inyuma ni itara ry''umutuku ariko iyo uburebure bwiyo mirongo cyangwa bw''utwo dutsiko burenga m6 impande zatwo cyangwa zayo zigaragazwa ku buryo bukurikira:', '', null, null, null, true, 241, false, 242),
('pdf2-q-089', 'amatara', 'Amatara ndangambere na ndanganyuma y''imodoka zitarengeje m 6 z''uburebure na m 2 z''ubugari habariwemo imitwaro kandi nta kindi kinyabiziga kiziritseho ashobora gusimburwa n''amatara yo guhagarara umwanya munini iyo ibyo binyabiziga bihagaze umwanya muto cyangwa munini mu nsisiro bibangikanye ku ruhande rw''umuhanda. Ayo matara arangwa n''amabara akurikira:', '', null, null, null, true, 242, false, 243),
