('pdf2-q-299', 'amatara', 'Umuyobozi w''ikinyabiziga yakora iki ahuye n''ikinyabiziga giturutse mukindi kerekezo, gicanye amatara yumuhondo aburira ?', '', null, null, null, true, 431, false, 432),
