-- Adds 372 questions from AMATEGEKO_YUMUHANDA_IBIBAZO_IBISUBIZO_2.pdf as DRAFTS
-- (published = false): learners see nothing until you publish them in the dashboard.
-- They are numbered #161 to #532. Pictures are bundled in the app
-- (assets/images/road_signs/pdf2/). There are no explanations yet.
--
-- Run 202611060001_questions_match_pdf.sql FIRST: this file stops unless the
-- highest question number is exactly 160. It runs as one transaction.
--
-- Categories: amatara 67, amategeko 71, ibimenyetso 74, imirongo 29, imyitwarire 41, modoka 60, umutekano 30.
begin;

do $$
begin
  if (select coalesce(max(number), 0) from public.questions) <> 160 then
    raise exception 'Expected the highest question number to be 160 (run 202611060001_questions_match_pdf.sql first). Nothing was changed.';
  end if;
end;
$$;



select setval('public.questions_number_seq', 532, true);

commit;

-- Check: expect 372 drafts numbered 161..532, each with 4 answers and exactly 1 correct.
select count(*) as drafts, min(q.number) as first_no, max(q.number) as last_no,
       min(c.answers) as min_answers, max(c.answers) as max_answers, min(c.correct) as min_correct, max(c.correct) as max_correct
from public.questions q
join (select question_id, count(*) as answers, count(*) filter (where is_correct) as correct
      from public.question_options group by question_id) c on c.question_id = q.id
where q.id like 'pdf2-q-%';
